let batchTemplate=null,batchTemplateRead=0;
const batchEsc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
function parseBambuTemplate(bytes,name){
 const files=fflate.unzipSync(bytes,{filter:file=>file.name==='Metadata/project_settings.config'&&file.originalSize<2000000});
 const bytesConfig=files['Metadata/project_settings.config'];if(!bytesConfig)throw Error('Choose a Bambu project saved with printer settings. A model-only 3MF cannot supply a printer profile.');
 const config=JSON.parse(fflate.strFromU8(bytesConfig));const nozzles=config.nozzle_diameter;if(!Array.isArray(nozzles)||!nozzles.length||nozzles.some(n=>!Number.isFinite(+n)||+n<=0))throw Error('The template has no supported nozzle configuration. Save a project from Bambu Studio with your printer selected.');
 const points=(config.printable_area||[]).map(p=>String(p).split('x').map(Number));if(points.length!==4||points.some(p=>p.length!==2||p.some(n=>!Number.isFinite(n))))throw Error('The template needs a rectangular Bambu build plate.');const xs=[...new Set(points.map(p=>p[0]))],ys=[...new Set(points.map(p=>p[1]))];if(xs.length!==2||ys.length!==2)throw Error('Only rectangular plate templates are supported.');
 const minX=Math.min(...xs),minY=Math.min(...ys),width=Math.max(...xs)-minX,depth=Math.max(...ys)-minY;if(width<=0||depth<=0)throw Error('The template has invalid plate dimensions.');
 // Printer connection information and author identities are not needed in a printable project.
 for(const key of Object.keys(config))if(/^(print_host$|printhost_|host_type$|device_id$|device_name$|access_code$|api_key$|serial$|cloud_user|user_id$|printer_ip$|printer_sn$)/i.test(key))delete config[key];
 return {name,config,width,depth,minX,minY,printer:String(config.printer_model||config.printer_settings_id||'Bambu printer'),nozzles:nozzles.map(Number),colors:Array.isArray(config.filament_colour)?config.filament_colour:[]};
}
function updateBatchControls(){const ready=items.filter(i=>i.stl).length;$('downloadBatch3MF').disabled=busy||ready<2||!batchTemplate;$('downloadIndividualZIP').disabled=busy||ready<2;$('batchTemplate').disabled=busy;$('batchDefault').disabled=busy;$('batchActiveProfile').textContent=batchTemplate?'Batch profile: '+batchTemplate.printer+' · '+batchTemplate.nozzles.join(' / ')+' mm nozzle':'Batch profile is not loaded. Choose a template below.';$('batchCount').textContent=ready?ready+' converted coaster'+(ready===1?'':'s')+' ready. One coaster per plate.':'Convert at least two coasters to create a multi-plate project.';}
function makeBatch3MF(coasters,template){
 if(!template)throw Error('Choose a Bambu printer project template first.');if(coasters.length<2)throw Error('Convert at least two coasters first.');if(coasters.length>MAX_BATCH_IMAGES)throw Error('CoasterPrint limits batches to 10 coasters per project. Use a smaller batch.');
 const config=JSON.parse(JSON.stringify(template.config)),esc=batchEsc;for(const key of ['wipe_tower_x','wipe_tower_y'])if(Array.isArray(config[key])&&config[key].length)config[key]=Array(coasters.length).fill(config[key][0]);const objects=[],assemblies=[],build=[],modelConfigs=[],plates=[],allMaterials=[],materialIndices=new Map();let nextID=1;const columns=Math.ceil(Math.sqrt(coasters.length));const plateSummary=[];
 const transforms=[];
 for(let index=0;index<coasters.length;index++){
  const item=coasters[index],result=item.stl,box=result.dimensions,w=box.max[0]-box.min[0],h=box.max[1]-box.min[1];if(w>template.width-10||h>template.depth-10)throw Error(item.file.name+': coaster does not fit this template’s plate with a 5 mm margin. Reduce its width and rebuild.');
  const parentID=nextID++,name=item.file.name.replace(/\.[^.]+$/,'');const cols=columns;const originX=(index%cols)*template.width*1.2,originY=-Math.floor(index/cols)*template.depth*1.2;const x=originX+template.minX+(template.width-w)/2-box.min[0],y=originY+template.minY+(template.depth-h)/2-box.min[1],z=-box.min[2];const transform='1 0 0 0 1 0 0 0 1 '+[x,y,z].join(' ');transforms.push({parentID,transform});
  const members=[{name:'Base '+result.baseMM+' mm',fill:'#D0D0D0',buffer:result.base.buffer},...result.parts.map(p=>({name:'Color '+String(p.index).padStart(2,'0')+' '+batchColorHex(p.fill),fill:batchColorHex(p.fill),buffer:p.buffer}))];const componentRefs=[],partMetadata=[];let faceCount=0;
  for(const part of members){const id=nextID++;if(!materialIndices.has(part.fill)){materialIndices.set(part.fill,allMaterials.length);allMaterials.push('<base name="'+esc(part.name)+'" displaycolor="'+part.fill+'FF"/>');}const materialIndex=materialIndices.get(part.fill);const mesh=batchSTLMesh(part.buffer);faceCount+=mesh.count;objects.push('<object id="'+id+'" name="'+esc(part.name)+'" type="model" pid="2147483000" pindex="'+materialIndex+'"><mesh>'+mesh.xml+'</mesh></object>');componentRefs.push('<component objectid="'+id+'"/>');
   const exact=template.colors.findIndex(c=>String(c).toUpperCase()===part.fill.toUpperCase()),extruder=exact>=0?exact+1:1;
   partMetadata.push('<part id="'+id+'" subtype="normal_part"><metadata key="name" value="'+esc(part.name)+'"/><metadata key="extruder" value="'+extruder+'"/><mesh_stat face_count="'+mesh.count+'" edges_fixed="0" degenerate_facets="0" facets_removed="0" facets_reversed="0" backwards_edges="0"/></part>');}
  assemblies.push('<object id="'+parentID+'" name="'+esc(name)+'" type="model"><components>'+componentRefs.join('')+'</components></object>');build.push('<item objectid="'+parentID+'" transform="'+transform+'"/>');modelConfigs.push('<object id="'+parentID+'"><metadata key="name" value="'+esc(name)+'"/><metadata key="extruder" value="1"/><metadata face_count="'+faceCount+'"/>'+partMetadata.join('')+'</object>');
  plates.push('<plate><metadata key="plater_id" value="'+(index+1)+'"/><metadata key="plater_name" value="'+esc(name)+'"/><metadata key="locked" value="false"/><model_instance><metadata key="object_id" value="'+parentID+'"/><metadata key="instance_id" value="0"/><metadata key="identify_id" value="'+(1000+index)+'"/></model_instance></plate>');plateSummary.push({plate:index+1,name,objectID:parentID,widthMM:w,depthMM:h,parts:members.length,origin:[originX,originY],translation:[x,y,z]});
 }
 // Bambu 2.8 skips all project/plate settings without a parsed BambuStudio Application version.
 // Keep the true generator explicit alongside the required project-dialect compatibility marker.
 const model='<?xml version="1.0" encoding="UTF-8"?><model unit="millimeter" xml:lang="en-US" xmlns="http://schemas.microsoft.com/3dmanufacturing/core/2015/02" xmlns:BambuStudio="http://schemas.bambulab.com/package/2021"><metadata name="Application">BambuStudio-02.08.02.61</metadata><metadata name="Description">Generated by CoasterPrint r21</metadata><metadata name="BambuStudio:3mfVersion">1</metadata><metadata name="Title">CoasterPrint multi-plate project</metadata><resources><basematerials id="2147483000">'+allMaterials.join('')+'</basematerials>'+objects.join('')+assemblies.join('')+'</resources><build>'+build.join('')+'</build></model>';
 const settings='<?xml version="1.0" encoding="UTF-8"?><config>'+modelConfigs.join('')+plates.join('')+'<assemble>'+transforms.map(t=>'<assemble_item object_id="'+t.parentID+'" instance_id="0" transform="'+t.transform+'" offset="0 0 0"/>').join('')+'</assemble></config>';
 const files={'[Content_Types].xml':'<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="model" ContentType="application/vnd.ms-package.3dmanufacturing-3dmodel+xml"/><Default Extension="config" ContentType="application/xml"/><Default Extension="json" ContentType="application/json"/></Types>',
 '_rels/.rels':'<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Target="/3D/3dmodel.model" Id="rel0" Type="http://schemas.microsoft.com/3dmanufacturing/2013/01/3dmodel"/></Relationships>',
 '3D/3dmodel.model':model,'Metadata/model_settings.config':settings,'Metadata/project_settings.config':JSON.stringify(config),'Metadata/coasterprint-plates.json':JSON.stringify({application:'CoasterPrint',printer:template.printer,columns,plates:plateSummary},null,2)};
 return fflate.zipSync(Object.fromEntries(Object.entries(files).map(([k,v])=>[k,fflate.strToU8(v)])),{level:6});
}
function batchColorHex(fill){const m=String(fill).match(/[\d.]+/g);return m&&m.length>=3?'#'+m.slice(0,3).map(n=>Math.round(+n).toString(16).padStart(2,'0')).join('').toUpperCase():/^#[\da-f]{6}$/i.test(fill)?fill.toUpperCase():'#808080';}
function batchSTLMesh(buffer){const view=new DataView(buffer),count=view.getUint32(80,true),vertices=[],triangles=[],map=new Map();for(let i=0;i<count;i++){const ids=[];for(let k=0;k<3;k++){const o=84+i*50+12+k*12,p=[view.getFloat32(o,true),view.getFloat32(o+4,true),view.getFloat32(o+8,true)],key=p.join(',');if(!map.has(key)){map.set(key,vertices.length);vertices.push('<vertex x="'+p[0]+'" y="'+p[1]+'" z="'+p[2]+'"/>');}ids.push(map.get(key));}triangles.push('<triangle v1="'+ids[0]+'" v2="'+ids[1]+'" v3="'+ids[2]+'"/>');}return {count,xml:'<vertices>'+vertices.join('')+'</vertices><triangles>'+triangles.join('')+'</triangles>'};}
async function downloadBatchProject(){const ready=items.filter(i=>i.stl);if(!batchTemplate){$('batchOptions').open=true;$('batchOptions').scrollIntoView({behavior:'smooth',block:'center'});$('batchProfile').textContent='Choose a project saved from your Bambu Studio to supply printer and plate settings.';$('batchTemplate').focus();return;}if(ready.length<2)return;busy=true;render();$('notice').textContent='Packing '+ready.length+' coasters onto separate plates…';await new Promise(r=>setTimeout(r,30));try{const bytes=makeBatch3MF(ready,batchTemplate);const url=URL.createObjectURL(new Blob([bytes],{type:'model/3mf'}));download(url,'coasterprint-'+ready.length+'-plate-project.3mf');setTimeout(()=>URL.revokeObjectURL(url),30000);const failed=items.length-ready.length;$('notice').textContent=ready.length+' plates exported using '+batchTemplate.printer+'. Open as a project in Bambu Studio and check filament assignments.'+(failed?' '+failed+' image(s) without a completed 3D model were excluded.':'');}catch(e){$('notice').textContent=e.message;}finally{busy=false;render();}}
$('batchTemplate').onchange=async e=>{const file=e.target.files[0];if(!file)return;const token=++batchTemplateRead;batchTemplate=null;updateBatchControls();try{if(file.size>64*1024*1024)throw Error('Use an unsliced Bambu project template smaller than 64 MB.');const bytes=new Uint8Array(await file.arrayBuffer());if(token!==batchTemplateRead)return;batchTemplate=parseBambuTemplate(bytes,file.name);$('batchProfile').textContent=batchTemplate.printer+' · '+batchTemplate.nozzles.join(' / ')+' mm nozzle · '+batchTemplate.width+' × '+batchTemplate.depth+' mm plate';}catch(e){if(token===batchTemplateRead)$('batchProfile').textContent=e.message;}updateBatchControls();};
$('downloadBatch3MF').onclick=downloadBatchProject;
$('downloadIndividualZIP').onclick=()=>{const ready=items.filter(i=>i.threeMF),files={};for(const item of ready)files[item.outname.replace(/\.svg$/,'.3mf')]=item.threeMF;const url=URL.createObjectURL(new Blob([fflate.zipSync(files,{level:6})],{type:'application/zip'}));download(url,'coasterprint-individual-models.zip');setTimeout(()=>URL.revokeObjectURL(url),30000);};

async function useDefaultBatchProfile(){const token=++batchTemplateRead;batchTemplate=null;updateBatchControls();$('batchProfile').textContent='Loading P1S / 0.4 mm starter profile…';try{const response=await fetch('presets/bambu-p1s-04.json');if(!response.ok)throw Error('Default profile could not load. Choose your own Bambu project template.');const config=await response.json();if(token!==batchTemplateRead)return;const archive=fflate.zipSync({'Metadata/project_settings.config':fflate.strToU8(JSON.stringify(config))});batchTemplate=parseBambuTemplate(archive,'CoasterPrint P1S / 0.4 mm starter');$('batchTemplate').value='';$('batchProfile').textContent='Default: '+batchTemplate.printer+' · 0.4 mm nozzle · '+batchTemplate.width+' × '+batchTemplate.depth+' mm plate';}catch(e){if(token===batchTemplateRead)$('batchProfile').textContent=e.message;}updateBatchControls();}
$('batchDefault').onclick=useDefaultBatchProfile;useDefaultBatchProfile();
